-- Generated by tools/gen_filter_sql.mjs from src/meta/wordFilter.js. Do not edit by hand.
-- Returns the first bad word found in t (same rules as the game), or null.
create or replace function public.bb_bad_word(t text) returns text
language plpgsql immutable set search_path = '' as $$
declare
  raw text := lower(coalesce(t, ''));
  n text;
  toks text[];
  cands text[];
  run text := '';
  tok text;
  w text;
  spaced text;
  i int;
begin
  foreach w in array array['1488', '14/88', '14 88']::text[] loop
    if position(w in raw) > 0 then return w; end if;
  end loop;
  n := replace(translate(raw, '0123456789@$!|€+àáâãäåāèéêëēìíîïīòóôõöøōùúûüūçñýÿ', 'oizeasgtbgasiietaaaaaaaeeeeeiiiiiooooooouuuuucnyy'), 'æ', 'ae');
  toks := array_remove(regexp_split_to_array(n, '[^a-z]+'), '');
  cands := toks;
  foreach tok in array toks loop
    if length(tok) = 1 then
      run := run || tok;
    else
      if length(run) > 1 then cands := cands || run; end if;
      run := '';
    end if;
  end loop;
  if length(run) > 1 then cands := cands || run; end if;
  for i in 1 .. 56 loop
    if exists (select 1 from unnest(cands) c where c ~ (array['f+u+c+k+', 'f+u+k+', 'f+c+k+', 'f+v+c+k+', 'p+h+u+c+k+', 'm+o+t+h+e+r+f+', 's+h+i+t+', 'b+i+t+c+h+', 'b+i+a+t+c+h+', 'b+a+s+t+a+r+d+', 'a+s+s+h+o+l+e+', 'a+r+s+e+h+o+l+e+', 'w+a+n+k+e+r+', 'b+o+l+l+o+c+k+', 'j+i+z+z+', 'd+i+c+k+h+e+a+d+', 'c+o+c+k+s+u+c+k+', 'b+l+o+w+j+o+b+', 'h+a+n+d+j+o+b+', 'd+i+l+d+o+', 'p+o+r+n+', 'h+e+n+t+a+i+', 'w+h+o+r+e+', 's+l+u+t+', 'p+u+s+s+i+e+s+', 'n+i+g+g+e+r+', 'n+i+g+g+a+', 'n+i+g+a+', 'f+a+g+g+o+t+', 'f+a+g+o+t+', 'r+e+t+a+r+d+e+d+', 't+r+a+n+n+y+', 'c+h+i+n+k+', 's+p+a+s+t+i+c+', 'h+i+t+l+e+r+', 'h+i+t+l+a+', 's+t+a+l+i+n+', 'n+a+z+i+', 's+i+e+g+h+e+i+l+', 'h+e+i+l+h+i+t+', 'h+o+l+o+c+a+u+s+t+', 'm+u+s+s+o+l+i+n+i+', 'p+o+l+p+o+t+', 'b+i+n+l+a+d+e+n+', 'k+u+k+l+u+x+k+l+a+n+', 'a+u+s+c+h+w+i+t+z+', 'g+o+e+b+b+e+l+s+', 'h+i+m+m+l+e+r+', 's+w+a+s+t+i+k+a+', 'h+a+k+e+n+k+r+e+u+z+', 'f+i+t+t+e+', 'f+i+t+t+e+t+r+y+n+e+', 'p+i+k+k+', 'k+u+k+s+u+g+e+r+', 'j+a+e+v+l+a+', 'j+a+v+l+a+']::text[])[i]) then return (array['fuck', 'fuk', 'fck', 'fvck', 'phuck', 'motherf', 'shit', 'bitch', 'biatch', 'bastard', 'asshole', 'arsehole', 'wanker', 'bollock', 'jizz', 'dickhead', 'cocksuck', 'blowjob', 'handjob', 'dildo', 'porn', 'hentai', 'whore', 'slut', 'pussies', 'nigger', 'nigga', 'niga', 'faggot', 'fagot', 'retarded', 'tranny', 'chink', 'spastic', 'hitler', 'hitla', 'stalin', 'nazi', 'siegheil', 'heilhit', 'holocaust', 'mussolini', 'polpot', 'binladen', 'kukluxklan', 'auschwitz', 'goebbels', 'himmler', 'swastika', 'hakenkreuz', 'fitte', 'fittetryne', 'pikk', 'kuksuger', 'jaevla', 'javla']::text[])[i]; end if;
  end loop;
  for i in 1 .. 37 loop
    if exists (select 1 from unnest(cands) c where c ~ (array['^a+s+s+$', '^a+r+s+e+$', '^c+u+n+t+$', '^c+u+n+t+s+$', '^d+i+c+k+$', '^d+i+c+k+s+$', '^c+o+c+k+$', '^c+o+c+k+s+$', '^c+u+m+$', '^s+e+x+$', '^s+e+x+y+$', '^t+i+t+s+$', '^t+i+t+t+i+e+s+$', '^b+o+o+b+s+$', '^p+e+n+i+s+$', '^v+a+g+i+n+a+$', '^r+a+p+e+$', '^r+a+p+e+d+$', '^r+a+p+i+n+g+$', '^r+a+p+i+s+t+$', '^t+w+a+t+$', '^f+a+g+$', '^f+a+g+s+$', '^r+e+t+a+r+d+$', '^p+u+s+s+y+$', '^h+e+i+l+$', '^k+k+k+$', '^i+s+i+s+$', '^n+s+f+w+$', '^n+u+d+e+$', '^n+u+d+e+s+$', '^n+a+k+e+d+$', '^h+o+r+n+y+$', '^h+o+r+e+$', '^k+u+k+$', '^n+e+g+e+r+$', '^f+a+e+n+$']::text[])[i]) then return (array['ass', 'arse', 'cunt', 'cunts', 'dick', 'dicks', 'cock', 'cocks', 'cum', 'sex', 'sexy', 'tits', 'titties', 'boobs', 'penis', 'vagina', 'rape', 'raped', 'raping', 'rapist', 'twat', 'fag', 'fags', 'retard', 'pussy', 'heil', 'kkk', 'isis', 'nsfw', 'nude', 'nudes', 'naked', 'horny', 'hore', 'kuk', 'neger', 'faen']::text[])[i]; end if;
  end loop;
  spaced := ' ' || array_to_string(toks, ' ') || ' ';
  foreach w in array array['sieg heil', 'white power']::text[] loop
    if position(' ' || w || ' ' in spaced) > 0 then return w; end if;
  end loop;
  return null;
end $$;

-- 007: word filter everywhere, hidden bad names, clip views, follows, Studio stats, stickers on
-- clips (text, emoji, pictures) and the picture storage. bb_bad_word comes first (generated).

-- ---------------------------------------------------------------- names
alter table public.profiles add column if not exists name_flagged boolean not null default false;
create or replace function public.bb_profile_name_check() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  -- Always recomputed by the server, so a player cannot clear it themselves.
  new.name_flagged := public.bb_bad_word(new.name) is not null;
  return new;
end $$;
drop trigger if exists profiles_name_check on public.profiles;
create trigger profiles_name_check before insert or update on public.profiles for each row execute function public.bb_profile_name_check();
update public.profiles set name_flagged = public.bb_bad_word(name) is not null;
create index if not exists profiles_flagged on public.profiles (name_flagged);

-- ---------------------------------------------------------------- clips: views, stickers, filter
alter table public.clips add column if not exists view_count int not null default 0;
alter table public.clips add column if not exists overlays jsonb not null default '[]'::jsonb;
create index if not exists clips_views on public.clips (view_count desc) where not hidden;
create index if not exists clips_title_search on public.clips (lower(title));

-- Stickers: up to 12 of { k: 'text' | 'emoji' | 'img', x, y (0..1 of the screen), s (size), v }.
-- Text is filtered; pictures must be in the uploader's own folder of the clip-pictures bucket.
create or replace function public.bb_check_overlays(o jsonb, who uuid) returns void
language plpgsql stable security definer set search_path = '' as $$
declare it jsonb; k text; v text;
begin
  if o is null then return; end if;
  if jsonb_typeof(o) <> 'array' then raise exception 'stickers: bad data'; end if;
  if jsonb_array_length(o) > 12 then raise exception 'stickers: at most 12'; end if;
  for it in select * from jsonb_array_elements(o) loop
    k := it->>'k';
    v := coalesce(it->>'v', '');
    if k not in ('text', 'emoji', 'img') then raise exception 'stickers: bad kind'; end if;
    if k = 'text' and (char_length(v) > 40 or public.bb_bad_word(v) is not null) then raise exception 'bad word: sticker text'; end if;
    if k = 'emoji' and char_length(v) > 8 then raise exception 'stickers: bad emoji'; end if;
    if k = 'img' and v not like 'https://wfsinljudtgjkzrulsdo.supabase.co/storage/v1/object/public/clip-pictures/' || who::text || '/%' then
      raise exception 'stickers: picture must be your own upload';
    end if;
  end loop;
end $$;

create or replace function public.bb_clip_before_insert() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (select count(*) from public.clips c where c.author = new.author and c.created_at > now() - interval '1 day') >= 15 then
    raise exception 'clip limit: 15 a day';
  end if;
  if public.bb_bad_word(new.title) is not null then raise exception 'bad word: title'; end if;
  perform public.bb_check_overlays(new.overlays, new.author);
  -- A flagged name is not shown on clips either.
  new.author_name := coalesce((select case when p.name_flagged then 'Player' else left(p.name, 16) end from public.profiles p where p.id = new.author), 'Player');
  new.like_count := 0;
  new.comment_count := 0;
  new.report_count := 0;
  new.view_count := 0;
  new.hidden := false;
  new.created_at := now();
  return new;
end $$;

create or replace function public.bb_clip_before_update() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if pg_trigger_depth() > 1 then return new; end if;
  new.author := old.author; new.author_name := old.author_name; new.title := old.title; new.data := old.data;
  new.duration := old.duration; new.mode := old.mode; new.arena := old.arena; new.created_at := old.created_at;
  new.like_count := old.like_count; new.comment_count := old.comment_count;
  new.view_count := old.view_count; new.overlays := old.overlays;
  if not new.hidden then new.report_count := 0; end if;
  return new;
end $$;

create or replace function public.bb_comment_before_insert() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (select count(*) from public.clip_comments c where c.author = new.author and c.created_at > now() - interval '10 minutes') >= 30 then
    raise exception 'comment limit: slow down';
  end if;
  if public.bb_bad_word(new.body) is not null then raise exception 'bad word: comment'; end if;
  new.author_name := coalesce((select case when p.name_flagged then 'Player' else left(p.name, 16) end from public.profiles p where p.id = new.author), 'Player');
  new.body := btrim(new.body);
  new.created_at := now();
  return new;
end $$;

-- Views: one per signed-in player per clip per day; viewers who are not signed in count too, but
-- at most 300 a day per clip (so a script cannot pump the number).
create table if not exists public.clip_views (
  clip_id uuid not null references public.clips (id) on delete cascade,
  viewer uuid references auth.users (id) on delete cascade,
  day date not null default current_date,
  n int not null default 1,
  created_at timestamptz not null default now()
);
create unique index if not exists clip_views_one on public.clip_views (clip_id, viewer, day) where viewer is not null;
create unique index if not exists clip_views_anon on public.clip_views (clip_id, day) where viewer is null;
create index if not exists clip_views_viewer on public.clip_views (viewer);
alter table public.clip_views enable row level security; -- no policies: only through bb_view_clip

create or replace function public.bb_view_clip(p_clip uuid) returns int
language plpgsql security definer set search_path = '' as $$
declare me uuid := auth.uid(); added int := 0;
begin
  if not exists (select 1 from public.clips where id = p_clip and not hidden) then return 0; end if;
  if me is not null then
    insert into public.clip_views (clip_id, viewer) values (p_clip, me) on conflict do nothing;
    get diagnostics added = row_count;
  else
    insert into public.clip_views (clip_id, viewer) values (p_clip, null)
      on conflict (clip_id, day) where viewer is null do update set n = public.clip_views.n + 1 where public.clip_views.n < 300;
    get diagnostics added = row_count;
  end if;
  if added > 0 then update public.clips set view_count = view_count + 1 where id = p_clip; end if;
  return (select view_count from public.clips where id = p_clip);
end $$;
grant execute on function public.bb_view_clip(uuid) to anon, authenticated;

-- ---------------------------------------------------------------- follows
create table if not exists public.follows (
  follower uuid not null default auth.uid() references auth.users (id) on delete cascade,
  followee uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (follower, followee),
  check (follower <> followee)
);
create index if not exists follows_followee on public.follows (followee);
alter table public.follows enable row level security;
drop policy if exists "follows: read" on public.follows;
create policy "follows: read" on public.follows for select using (true);
drop policy if exists "follows: add own" on public.follows;
create policy "follows: add own" on public.follows for insert to authenticated with check (follower = (select auth.uid()));
drop policy if exists "follows: remove own" on public.follows;
create policy "follows: remove own" on public.follows for delete to authenticated using (follower = (select auth.uid()));
create or replace function public.bb_follow_limit() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (select count(*) from public.follows f where f.follower = new.follower) >= 500 then raise exception 'follow limit: 500'; end if;
  return new;
end $$;
drop trigger if exists follow_limit on public.follows;
create trigger follow_limit before insert on public.follows for each row execute function public.bb_follow_limit();

-- ---------------------------------------------------------------- Studio
-- Your clips with their numbers, views per day for the last 14 days, and your followers.
create or replace function public.bb_studio() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'followers', (select count(*) from public.follows f where f.followee = auth.uid()),
    'clips', coalesce((select jsonb_agg(jsonb_build_object(
        'id', c.id, 'title', c.title, 'mode', c.mode, 'arena', c.arena, 'duration', c.duration, 'created_at', c.created_at,
        'views', c.view_count, 'likes', c.like_count, 'comments', c.comment_count, 'hidden', c.hidden) order by c.created_at desc)
      from public.clips c where c.author = auth.uid()), '[]'::jsonb),
    'daily', coalesce((select jsonb_agg(jsonb_build_object('day', d.day, 'views', d.views) order by d.day)
      from (select v.day, sum(v.n)::int as views from public.clip_views v join public.clips c on c.id = v.clip_id
            where c.author = auth.uid() and v.day > current_date - 14 group by v.day) d), '[]'::jsonb)
  );
$$;
revoke execute on function public.bb_studio() from public, anon;
grant execute on function public.bb_studio() to authenticated;

-- ---------------------------------------------------------------- picture storage
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('clip-pictures', 'clip-pictures', true, 307200, array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do update set public = true, file_size_limit = 307200, allowed_mime_types = array['image/png', 'image/jpeg', 'image/webp'];
drop policy if exists "clip pictures: upload own" on storage.objects;
create policy "clip pictures: upload own" on storage.objects for insert to authenticated
  with check (bucket_id = 'clip-pictures' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists "clip pictures: delete own" on storage.objects;
create policy "clip pictures: delete own" on storage.objects for delete to authenticated
  using (bucket_id = 'clip-pictures' and (storage.foldername(name))[1] = (select auth.uid())::text);

revoke execute on function public.bb_check_overlays(jsonb, uuid) from public, anon, authenticated;
revoke execute on function public.bb_profile_name_check() from public, anon, authenticated;
revoke execute on function public.bb_follow_limit() from public, anon, authenticated;
revoke execute on function public.bb_clip_before_insert() from public, anon, authenticated;
revoke execute on function public.bb_clip_before_update() from public, anon, authenticated;
revoke execute on function public.bb_comment_before_insert() from public, anon, authenticated;
